package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"postflip/rw"
)

var headerRx = regexp.MustCompile(`Code generated by j2go from (\S+\.java)\.`)

// findFamily reads the Java class headers of the generated files: the F-bounded bases and
// their subclasses' substitutions.
func findFamily(javaRoot string) {
	javaOf := map[string]*javaClass{} // Go type name -> its Java class (top-level classes only)
	fileOf := map[string]*ast.File{}
	for _, f := range rw.Files {
		if !isG(f) {
			continue
		}
		src := rw.Src[rw.Fset.File(f.Pos())]
		m := headerRx.FindSubmatch(src[:min(len(src), 300)])
		if m == nil {
			continue
		}
		jc := readJava(filepath.Join(javaRoot, string(m[1])))
		if jc == nil {
			continue
		}
		javaOf[jc.name] = jc
		fileOf[jc.name] = f
	}
	// candidates: every parameter bounded, some F-bounded
	cand := map[string]*javaClass{}
	for n, jc := range javaOf {
		if len(jc.params) == 0 || len(jc.bounds) != len(jc.params) {
			continue
		}
		fb := false
		for _, p := range jc.params {
			fb = fb || jc.fbound[p]
		}
		if fb {
			cand[n] = jc
		}
	}
	// a family: the bounds of every parameter are candidates
	for n, jc := range cand {
		ok := true
		for _, b := range jc.bounds {
			if cand[b] == nil {
				ok = false
			}
		}
		if !ok {
			continue
		}
		tn, _ := rw.Pkg.Scope().Lookup(n).(*types.TypeName)
		if tn == nil {
			continue
		}
		b := &base{tn: tn, named: tn.Type().(*types.Named), jc: jc, file: fileOf[n], decls: map[string]*ast.FuncDecl{}, movedField: map[*types.Var]*ast.Field{}, ifaceFields: map[string]*ast.Field{}}
		bases[tn] = b
	}
	if len(bases) == 0 {
		return
	}
	// subclasses: structs that embed a base, with their Java `extends Base<A, B>`
	for _, f := range rw.Files {
		if !isG(f) {
			continue
		}
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok {
				continue
			}
			for _, sp := range gd.Specs {
				ts, ok := sp.(*ast.TypeSpec)
				if !ok {
					continue
				}
				st, ok := ts.Type.(*ast.StructType)
				if !ok {
					continue
				}
				tn := rw.Info.Defs[ts.Name].(*types.TypeName)
				if b := bases[tn]; b != nil {
					b.spec = ts
					for _, fl := range st.Fields.List {
						for _, nm := range fl.Names {
							v := rw.Info.Defs[nm].(*types.Var)
							if nm.Name == "self_" {
								if it, ok := rw.Info.ObjectOf(identOf(fl.Type)).(*types.TypeName); ok {
									b.ifaceName = it.Name()
								}
								continue
							}
							if mentionsErased(v.Type()) {
								b.moved = append(b.moved, v)
								b.movedField[v] = fl
							}
						}
					}
					continue
				}
				if len(st.Fields.List) == 0 || len(st.Fields.List[0].Names) != 0 {
					continue
				}
				emb := ptrNamedOrNamed(rw.Info.Types[st.Fields.List[0].Type].Type)
				b := bases[emb]
				if b == nil {
					continue
				}
				jc := javaOf[ts.Name.Name]
				if jc == nil || jc.extends != b.tn.Name() || len(jc.extArgs) != len(b.jc.params) {
					fmt.Fprintf(os.Stderr, "fbound: %s extends %s without its type arguments: not handled\n", ts.Name.Name, b.tn.Name())
					os.Exit(1)
				}
				s := &sub{tn: tn, named: tn.Type().(*types.Named), b: b, sigma: map[*types.TypeName]*types.TypeName{}, file: f, spec: ts, embed: st.Fields.List[0], decls: map[string]*ast.FuncDecl{}}
				for i, p := range b.jc.params {
					er := erasedOf(b, p)
					to, _ := rw.Pkg.Scope().Lookup(strings.ReplaceAll(jc.extArgs[i], ".", "_")).(*types.TypeName)
					if er == nil || to == nil {
						fmt.Fprintf(os.Stderr, "fbound: %s: type argument %s not found\n", ts.Name.Name, jc.extArgs[i])
						os.Exit(1)
					}
					s.sigma[er] = to
				}
				subs[tn] = s
				b.subs = append(b.subs, s)
			}
		}
	}
	// closed hierarchy: nothing extends a subclass
	for _, f := range rw.Files {
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok {
				continue
			}
			for _, sp := range gd.Specs {
				ts, ok := sp.(*ast.TypeSpec)
				if !ok {
					continue
				}
				if st, ok := ts.Type.(*ast.StructType); ok && len(st.Fields.List) > 0 && len(st.Fields.List[0].Names) == 0 {
					if s := subs[ptrNamedOrNamed(rw.Info.Types[st.Fields.List[0].Type].Type)]; s != nil {
						fmt.Fprintf(os.Stderr, "fbound: %s extends %s: the hierarchy is not closed, not handled\n", ts.Name.Name, s.tn.Name())
						os.Exit(1)
					}
				}
			}
		}
	}
	// methods
	for _, f := range rw.Files {
		if !isG(f) {
			continue
		}
		for _, d := range f.Decls {
			if gd, ok := d.(*ast.GenDecl); ok {
				for _, sp := range gd.Specs {
					if ts, ok := sp.(*ast.TypeSpec); ok {
						for _, b := range bases {
							if ts.Name.Name == b.ifaceName {
								b.iface = ts
								for _, m := range ts.Type.(*ast.InterfaceType).Methods.List {
									b.ifaceFields[m.Names[0].Name] = m
								}
							}
						}
					}
				}
				continue
			}
			fd := d.(*ast.FuncDecl)
			if fd.Recv == nil {
				for _, b := range bases {
					if fd.Name.Name == "new_"+b.tn.Name() {
						b.newFn = fd
					}
				}
				continue
			}
			rt := ptrNamed(rw.Info.Types[fd.Recv.List[0].Type].Type)
			if b := bases[rt]; b != nil {
				b.decls[fd.Name.Name] = fd
				b.order = append(b.order, fd)
			}
			if s := subs[rt]; s != nil {
				s.decls[fd.Name.Name] = fd
			}
		}
	}
	for _, b := range bases {
		if b.iface != nil && b.iface.Name.Name != b.ifaceName {
			b.iface = nil
		}
		// self_ declared by the base itself
		own := false
		st := b.spec.Type.(*ast.StructType)
		for _, fl := range st.Fields.List {
			for _, nm := range fl.Names {
				own = own || nm.Name == "self_"
			}
		}
		if !own {
			b.iface = nil
		}
	}
}

func identOf(e ast.Expr) *ast.Ident {
	switch x := e.(type) {
	case *ast.Ident:
		return x
	case *ast.StarExpr:
		return identOf(x.X)
	}
	return nil
}

func isInfra(b *base, name string) bool {
	return name == "self" || name == "as_"+b.tn.Name() || strings.HasPrefix(name, "up_") || name == "zero_"+b.tn.Name() || name == "finit_"+b.tn.Name()
}

// dispatchTarget: a dispatcher's body is `return this.self_.K(args)` (or the call as a
// statement), self_ the base's own field.
func dispatchTarget(b *base, fd *ast.FuncDecl) string {
	if b.iface == nil || fd.Body == nil || len(fd.Body.List) != 1 {
		return ""
	}
	var call *ast.CallExpr
	switch s := fd.Body.List[0].(type) {
	case *ast.ReturnStmt:
		if len(s.Results) == 1 {
			call, _ = s.Results[0].(*ast.CallExpr)
		}
	case *ast.ExprStmt:
		call, _ = s.X.(*ast.CallExpr)
	}
	if call == nil {
		return ""
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	inner, ok := sel.X.(*ast.SelectorExpr)
	if !ok || inner.Sel.Name != "self_" {
		return ""
	}
	if id, ok := inner.X.(*ast.Ident); !ok || id.Name != "this" {
		return ""
	}
	if b.ifaceFields[sel.Sel.Name] == nil {
		return ""
	}
	return sel.Sel.Name
}

// isWrapper: a subclass's `if p, _ := this.self_.(*C); p == this { return this.K(..) }; return this.self_.K(..)`
func isWrapper(fd *ast.FuncDecl) string {
	if fd.Body == nil || len(fd.Body.List) != 2 {
		return ""
	}
	is, ok := fd.Body.List[0].(*ast.IfStmt)
	if !ok || is.Init == nil {
		return ""
	}
	as, ok := is.Init.(*ast.AssignStmt)
	if !ok || len(as.Rhs) != 1 {
		return ""
	}
	ta, ok := as.Rhs[0].(*ast.TypeAssertExpr)
	if !ok || rw.Text(ta.X) != "this.self_" {
		return ""
	}
	var call *ast.CallExpr
	switch s := fd.Body.List[1].(type) {
	case *ast.ReturnStmt:
		if len(s.Results) == 1 {
			call, _ = s.Results[0].(*ast.CallExpr)
		}
	case *ast.ExprStmt:
		call, _ = s.X.(*ast.CallExpr)
	}
	if call == nil {
		return ""
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || rw.Text(sel.X) != "this.self_" {
		return ""
	}
	return sel.Sel.Name
}

// exactlyIdiom: `p` of `if p, _ := this.self_.(*B); p == this` (the dispatch fast path)
func exactlyIdiom(e ast.Expr) bool {
	for p := rw.Parent[e]; p != nil; p = rw.Parent[p] {
		if as, ok := p.(*ast.AssignStmt); ok {
			if len(as.Rhs) == 1 {
				if ta, ok := as.Rhs[0].(*ast.TypeAssertExpr); ok && rw.Text(ta.X) == "this.self_" {
					return true
				}
			}
			return false
		}
		if is, ok := p.(*ast.IfStmt); ok {
			if is.Init != nil {
				if as, ok := is.Init.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
					if ta, ok := as.Rhs[0].(*ast.TypeAssertExpr); ok && rw.Text(ta.X) == "this.self_" {
						if be, ok := is.Cond.(*ast.BinaryExpr); ok && (be.X == e || be.Y == e) {
							return true
						}
					}
				}
			}
			return false
		}
		if _, ok := p.(ast.Stmt); ok {
			return false
		}
	}
	return false
}

// erasedUse reports whether the body of fd has an expression of a type mentioning the erased
// bases (other than the receiver and the dispatch fast path) or reads a moved field.
func erasedUse(b *base, fd *ast.FuncDecl) bool {
	if fd == nil || fd.Body == nil {
		return false
	}
	recv := rw.Info.Defs[fd.Recv.List[0].Names[0]]
	found := false
	ast.Inspect(fd.Body, func(n ast.Node) bool {
		if found {
			return false
		}
		e, ok := n.(ast.Expr)
		if !ok {
			return true
		}
		if id, ok := e.(*ast.Ident); ok && rw.Info.Uses[id] == recv {
			return true
		}
		if sel, ok := e.(*ast.SelectorExpr); ok {
			if s := rw.Info.Selections[sel]; s != nil && s.Kind() == types.FieldVal && movedOwner(s.Obj().(*types.Var)) != nil {
				found = true
				return false
			}
		}
		if exactlyIdiom(e) {
			return false
		}
		if ta, ok := e.(*ast.TypeAssertExpr); ok && rw.Text(ta.X) == "this.self_" {
			return false
		}
		if tv, ok := rw.Info.Types[e]; ok && tv.Type != nil {
			if _, isFunc := tv.Type.(*types.Signature); isFunc {
				return true // a method or function value: its calls are what counts
			}
		}
		if tv, ok := rw.Info.Types[e]; ok && !tv.IsType() && tv.Type != nil && mentionsErased(tv.Type) {
			found = true
			return false
		}
		if tv, ok := rw.Info.Types[e]; ok && tv.IsType() && mentionsErased(tv.Type) {
			found = true
			return false
		}
		return true
	})
	return found
}

func sigErased(fd *ast.FuncDecl) bool {
	if fd == nil {
		return false
	}
	sig := rw.Info.Defs[fd.Name].Type().(*types.Signature)
	for i := 0; i < sig.Params().Len(); i++ {
		if mentionsErased(sig.Params().At(i).Type()) {
			return true
		}
	}
	for i := 0; i < sig.Results().Len(); i++ {
		if mentionsErased(sig.Results().At(i).Type()) {
			return true
		}
	}
	return false
}

func buildGroups() {
	for _, b := range sortedBases() {
		implOf := map[string]bool{}
		var gs []*group
		for _, fd := range b.order {
			if k := dispatchTarget(b, fd); k != "" {
				implOf[k] = true
				gs = append(gs, &group{b: b, name: fd.Name.Name, d: fd, impl: b.decls[k], implName: k})
			}
		}
		for _, fd := range b.order {
			if implOf[fd.Name.Name] || dispatchTarget(b, fd) != "" || isInfra(b, fd.Name.Name) {
				continue
			}
			gs = append(gs, &group{b: b, name: fd.Name.Name, impl: fd, implName: fd.Name.Name})
		}
		in := map[*group]bool{}
		byObj := map[types.Object]*group{}
		for _, g := range gs {
			if g.d != nil {
				byObj[rw.Info.Defs[g.d.Name]] = g
			}
			if g.impl != nil {
				byObj[rw.Info.Defs[g.impl.Name]] = g
			}
			jr := b.jc.results[g.name]
			for _, p := range b.jc.params {
				if jr == p {
					var gf *ast.FuncDecl = g.d
					if gf == nil {
						gf = g.impl
					}
					r := rw.Info.Defs[gf.Name].Type().(*types.Signature).Results()
					if r.Len() == 1 && types.IsInterface(r.At(0).Type()) {
						g.ires = r.At(0).Type()
						g.jparam = p
					}
				}
			}
			if sigErased(g.d) || sigErased(g.impl) || erasedUse(b, g.impl) || g.ires != nil {
				in[g] = true
			}
		}
		// the methods whose body calls one of them on this
		for changed := true; changed; {
			changed = false
			for _, g := range gs {
				if in[g] || g.impl == nil {
					continue
				}
				ast.Inspect(g.impl.Body, func(n ast.Node) bool {
					c, ok := n.(*ast.CallExpr)
					if !ok {
						return true
					}
					if sel, ok := c.Fun.(*ast.SelectorExpr); ok {
						if s := rw.Info.Selections[sel]; s != nil && s.Kind() == types.MethodVal {
							if gg := byObj[s.Obj()]; gg != nil && in[gg] && rw.Text(sel.X) == "this" {
								in[g] = true
								changed = true
							}
						}
					}
					return true
				})
			}
		}
		for _, g := range gs {
			if !in[g] {
				continue
			}
			g.tname = g.name
			if g.ires != nil {
				g.tname = g.name + "T_"
			}
			// written out already (a rerun): every subclass declares the typed method itself
			done := len(b.subs) > 0
			for _, s := range b.subs {
				d := s.decls[g.tname]
				if d == nil || isWrapper(d) != "" || (g.d != nil && g.tname == g.implName) {
					done = false
				}
			}
			if done {
				continue
			}
			g.superUsed = map[*sub]bool{}
			groups = append(groups, g)
			if g.d != nil {
				groupOf[rw.Info.Defs[g.d.Name]] = g
			}
			if g.impl != nil {
				groupOf[rw.Info.Defs[g.impl.Name]] = g
				copyDecl[g.impl] = g
				gdecls[g.impl] = true
			}
			if g.d != nil {
				gdecls[g.d] = true
			}
			for _, s := range b.subs {
				if o := s.decls[g.implName]; o != nil {
					groupOf[rw.Info.Defs[o.Name]] = g
					copyDecl[o] = g
					ownerSub[o] = s
					gdecls[o] = true
				}
				if w := s.decls[g.name]; w != nil && w != s.decls[g.implName] {
					groupOf[rw.Info.Defs[w.Name]] = g
					ownerSub[w] = s
					gdecls[w] = true
					if isWrapper(w) == "" {
						fmt.Fprintf(os.Stderr, "fbound: %s.%s overrides %s.%s without the dispatch: not handled\n", s.tn.Name(), w.Name.Name, b.tn.Name(), g.name)
						os.Exit(1)
					}
				}
				if g.impl == nil && s.decls[g.implName] == nil {
					fmt.Fprintf(os.Stderr, "fbound: %s has no %s\n", s.tn.Name(), g.implName)
					os.Exit(1)
				}
			}
		}
	}
	// super calls in the subclasses' overrides
	for o, s := range ownerSub {
		ast.Inspect(o.Body, func(n ast.Node) bool {
			if c, ok := n.(*ast.CallExpr); ok {
				if g, _, sup, _ := groupCall(c); g != nil && sup {
					if s.decls[g.implName] != nil && copyDecl[s.decls[g.implName]] != nil {
						g.superUsed[s] = true
					}
				}
			}
			return true
		})
	}
}

// computeKept: the base keeps a method that code holding the erased base calls (outside the
// methods the step writes out), and what the kept bodies call.
func computeKept() {
	visit := func(body ast.Node) {
		ast.Inspect(body, func(n ast.Node) bool {
			c, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			if g, cs, sup, _ := groupCall(c); g != nil && cs == nil && !sup {
				g.kept = true
			}
			return true
		})
	}
	for _, f := range rw.Files {
		if !isG(f) {
			continue
		}
		for _, d := range f.Decls {
			if fd, ok := d.(*ast.FuncDecl); ok && (gdecls[fd] || isNewFn(fd)) {
				continue
			}
			visit(d)
		}
	}
	for changed := true; changed; {
		changed = false
		for _, g := range groups {
			if !g.kept || g.d != nil || g.toDisp {
				continue
			}
			if readsMoved(g.impl) {
				if g.b.iface == nil {
					fmt.Fprintf(os.Stderr, "fbound: %s.%s is called on the erased base and reads a moved field, and %s has no dispatch interface: not handled\n", g.b.tn.Name(), g.name, g.b.tn.Name())
					os.Exit(1)
				}
				g.toDisp = true
				changed = true
				continue
			}
			before := countKept()
			visit(g.impl.Body)
			if countKept() != before {
				changed = true
			}
		}
	}
	for _, b := range bases {
		if b.newFn != nil && len(rw.UsesOf[rw.Info.Defs[b.newFn.Name]]) > 0 {
			fmt.Fprintf(os.Stderr, "fbound: %s is instantiated (new_%s): not handled\n", b.tn.Name(), b.tn.Name())
			os.Exit(1)
		}
	}
}

func countKept() int {
	n := 0
	for _, g := range groups {
		if g.kept {
			n++
		}
	}
	return n
}

func readsMoved(fd *ast.FuncDecl) bool {
	found := false
	ast.Inspect(fd, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if s := rw.Info.Selections[sel]; s != nil && s.Kind() == types.FieldVal && movedOwner(s.Obj().(*types.Var)) != nil {
				found = true
			}
		}
		return !found
	})
	return found
}

func isNewFn(fd *ast.FuncDecl) bool {
	for _, b := range bases {
		if b.newFn == fd {
			return true
		}
	}
	return false
}
